function entry({ id, category, question, supportedRoles, navigation, answer, status = 'implemented', sources, tests }) {
  return {
    id,
    category,
    question,
    supportedRoles,
    navigation,
    verifiedAnswer: answer,
    implementationStatus: status,
    sourceReferences: sources,
    verificationStatus: 'SOURCE_VERIFIED',
    assistantTests: tests,
  };
}

export const catalog = [
  // Customers, prospects and estimates (20)
  entry({ id: 'CPE-01', category: 'Customers, prospects and estimates', question: 'How do I create a request for an estimate for a new or prospective customer?', supportedRoles: ['owner','admin','manager'], navigation: 'Customers > New Inquiry > Create inquiry for a new prospect', answer: 'Open Customers and choose New Inquiry. Choose Create inquiry for a new prospect, enter contact, service property, Service requested, category and follow-up details, then Save inquiry. From the saved inquiry choose Schedule Estimate. Do not start with Schedule New Job.', sources: customers, tests: [procedure('manager','/customers',[['customers'],['new inquiry'],['new prospect'],['service property'],['schedule estimate'],['do not','schedule new job']]), procedure('owner','/customers',[['new inquiry'],['prospect'],['schedule estimate']])] }),
  entry({ id: 'CPE-02', category: 'Customers, prospects and estimates', question: 'How do I schedule an estimate visit for an existing customer?', supportedRoles: ['owner','admin','manager'], navigation: 'Customers > New Inquiry > Find existing customer > Use this customer > Save inquiry > Schedule Estimate', answer: 'Create an inquiry, search for and select the existing customer and property, describe the requested service, save, then choose Schedule Estimate and review date, quarter-hour time, property and eligible field worker.', sources: customers, tests: [procedure('manager','/customers',[['new inquiry'],['existing customer','search'],['schedule estimate'],['quarter-hour','time'],['eligible','field worker','technician']])] }),
  entry({ id: 'CPE-03', category: 'Customers, prospects and estimates', question: 'How do I add a customer without first creating an inquiry?', supportedRoles: ['owner','admin','manager'], navigation: 'Customers > Add Customer', answer: 'On Customers choose Add Customer, enter identity/contact and address fields, then save. Use New Inquiry instead when the contact is still a prospect requesting an estimate.', sources: customerRecords, tests: [procedure('manager','/customers',[['customers'],['add customer'],['new inquiry','prospect']])] }),
  entry({ id: 'CPE-04', category: 'Customers, prospects and estimates', question: 'How does Route Logistics prevent a duplicate prospect or customer?', supportedRoles: ['owner','admin','manager'], navigation: 'Customers > New Inquiry > Find matching customers', answer: 'Search existing customers by name, email, phone or service address. If possible matches appear, reuse the correct record; creating a separate prospect requires explicit confirmation and a reason.', sources: customers, tests: [procedure('manager','/customers',[['search'],['existing customer'],['separate prospect','duplicate'],['reason']])] }),
  entry({ id: 'CPE-05', category: 'Customers, prospects and estimates', question: 'How do I manage more than one service property for a customer?', supportedRoles: ['owner','admin','manager'], navigation: 'Customers > View customer > Service properties', answer: 'Open the customer, use the Service properties section to add or edit labeled properties, validate the service address and save. Scheduling must select the property where service occurs, not the billing address.', sources: customerRecords, tests: [procedure('manager','/customers',[['customer'],['service propert'],['add','edit'],['service address','billing']])] }),
  entry({ id: 'CPE-06', category: 'Customers, prospects and estimates', question: 'Can I change the service property while creating an appointment and save it permanently?', supportedRoles: ['owner','admin','manager'], navigation: 'Jobs > New Job > Service property > Enable Editing', answer: 'Choose Enable Editing before changing the populated address. Google validation is advisory for internal scheduling. Select the option to save the address to the customer when the change should be permanent; otherwise it applies only to the job.', sources: jobs, tests: [procedure('manager','/jobs',[['enable editing'],['google','address'],['permanent','customer'],['job']])] }),
  entry({ id: 'CPE-07', category: 'Customers, prospects and estimates', question: 'How do I check whether a prospect property is inside our service area?', supportedRoles: ['owner','admin','manager'], navigation: 'Customers > New Inquiry > Check coverage / owner exception', answer: 'Enter the service property and category, expand Check coverage / owner exception, and run the eligibility check. An authorized owner can approve an explicit out-of-area exception; the server rechecks eligibility.', sources: [...customers,'routeLogisticsWeb/src/components/ServicePropertyEligibility.jsx','functions/serviceAreas.js'], tests: [procedure('manager','/customers',[['check coverage'],['service property'],['category'],['owner','exception'],['server']])] }),
  entry({ id: 'CPE-08', category: 'Customers, prospects and estimates', question: 'How do I assign an estimate visit to a field worker?', supportedRoles: ['owner','admin','manager'], navigation: 'Customers > inquiry > Schedule Estimate > Assigned technician', answer: 'From the saved inquiry choose Schedule Estimate. In the scheduling dialog confirm the Estimate visit kind, select an eligible field worker under Assigned technician, review conflicts and alternatives, then save.', sources: [...customers,...jobs], tests: [procedure('manager','/customers',[['schedule estimate'],['assigned technician','field worker'],['eligible'],['conflict','alternative']])] }),
  entry({ id: 'CPE-09', category: 'Customers, prospects and estimates', question: 'How does a technician open an assigned estimate visit?', supportedRoles: ['technician','owner','admin','manager'], navigation: 'Mobile > Field > assigned work order > Prepare Estimate', answer: 'In Field mode open the assigned estimate visit, complete the visit workflow, then choose Prepare Estimate. Technicians can prepare only an assigned estimate and cannot approve it as management.', sources: estimates, tests: [procedure('technician','/my-work',[['my work','assigned'],['prepare estimate'],['cannot','management','approve']])] }),
  entry({ id: 'CPE-10', category: 'Customers, prospects and estimates', question: 'How do I add labor to an estimate?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: 'Estimates > open draft > Add labor line', answer: 'Open the draft, choose Add labor line, enter description, quantity and unit price, then save the versioned draft. Server calculation determines totals.', sources: estimates, tests: [procedure('manager','/estimates',[['estimates'],['labor'],['description'],['quantity'],['unit price'],['save','version']])] }),
  entry({ id: 'CPE-11', category: 'Customers, prospects and estimates', question: 'How do I add materials to an estimate?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: 'Estimates > open draft > Add material line', answer: 'Open the draft, choose Add material line, enter description, quantity and unit price, then save the versioned draft.', sources: estimates, tests: [procedure('technician','/estimates',[['estimate'],['material'],['description'],['quantity'],['unit price'],['save']])] }),
  entry({ id: 'CPE-12', category: 'Customers, prospects and estimates', question: 'Can I add notes and photos to an estimate?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: 'Estimates > open draft > Notes / Camera / Gallery', answer: 'Yes. Add scope/notes and capture or select photos in the estimate draft. Photos are retained locally until uploaded and attached to a saved version; keep the draft until synchronization is confirmed.', sources: estimates, tests: [procedure('technician','/estimates',[['notes'],['photo'],['draft'],['save','upload'],['sync']])] }),
  entry({ id: 'CPE-13', category: 'Customers, prospects and estimates', question: 'Can I prepare and save an estimate while the mobile app is offline?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: 'Mobile > Estimates > edit assigned estimate', answer: 'A previously loaded assigned estimate can be edited offline. The app shows saved-on-device or waiting-to-sync state and retries after reconnection. It must not be treated as server-saved until synchronization succeeds.', sources: estimates, tests: [procedure('technician','/estimates',[['offline'],['saved','device'],['waiting','sync'],['reconnect']])] }),
  entry({ id: 'CPE-14', category: 'Customers, prospects and estimates', question: 'How do I create or share an estimate PDF?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: 'Estimates > open saved version > Share estimate PDF', answer: 'Open the saved estimate version and choose Share estimate PDF. Customer email delivery is a separate action and may require management approval and enabled email.', sources: estimates, tests: [procedure('manager','/estimates',[['estimate'],['pdf'],['share'],['email','separate'],['approval']])] }),
  entry({ id: 'CPE-15', category: 'Customers, prospects and estimates', question: 'How does a technician submit an estimate for management review?', supportedRoles: ['technician-assigned'], navigation: 'Mobile > Estimates > saved server version > Submit for Review', answer: 'Save and synchronize the exact draft version first, then choose Submit for Review. The version becomes read-only for the technician while management reviews it.', sources: estimates, tests: [procedure('technician','/estimates',[['save','synchronize'],['submit for review'],['version'],['management']])] }),
  entry({ id: 'CPE-16', category: 'Customers, prospects and estimates', question: 'How does a manager approve an estimate or request changes?', supportedRoles: ['owner','admin','manager'], navigation: 'Estimates > open submitted version > Approve for delivery / Request changes', answer: 'Open the submitted version. Enter review comments as needed, then choose Approve for delivery or Request changes. Approval applies only to that exact version.', sources: estimates, tests: [procedure('manager','/estimates',[['submitted','version'],['approve for delivery'],['request changes'],['exact','version']])] }),
  entry({ id: 'CPE-17', category: 'Customers, prospects and estimates', question: 'How is an approved estimate sent to the customer?', supportedRoles: ['owner','admin','manager'], navigation: 'Estimates > approved version > Email approved estimate', answer: 'After management approves the exact version, choose Email approved estimate and monitor delivery status. A technician can send directly only if the company owner enabled that policy.', sources: estimates, tests: [procedure('manager','/estimates',[['approve'],['email approved estimate'],['delivery status'],['technician','owner','policy']])] }),
  entry({ id: 'CPE-18', category: 'Customers, prospects and estimates', question: 'How can a customer approve, decline, or request a revision to an estimate?', supportedRoles: ['customer'], navigation: 'Secure estimate email link > approval page', answer: 'The customer opens the secure estimate link and acts on the exact version: approve, decline, or request a revision. A later edit creates a new version and does not rewrite the earlier decision.', sources: ['routeLogisticsWeb/src/pages/EstimateApprovalPage.jsx','functions/estimates.js'], tests: [procedure('manager','/estimates',[['customer'],['approve'],['decline'],['revision'],['version']])] }),
  entry({ id: 'CPE-19', category: 'Customers, prospects and estimates', question: 'How do I revise an estimate after changes are requested?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: 'Estimates > revision-requested estimate > edit and save new version', answer: 'Open the revision-requested estimate, review management/customer comments, edit the draft, save a new immutable version, and submit or approve that version through the normal workflow.', sources: estimates, tests: [procedure('technician','/estimates',[['revision'],['comments'],['new','version'],['submit']])] }),
  entry({ id: 'CPE-20', category: 'Customers, prospects and estimates', question: 'How do I schedule work after a customer approves an estimate?', supportedRoles: ['owner','admin','manager'], navigation: 'Estimates > Approved — scheduling needed > Convert approved estimate', answer: 'Open Estimates and locate the estimate marked Approved — scheduling needed. Choose Convert approved estimate to job, confirm required property/category or prospect conversion details, choose date and quarter-hour time, then explicitly convert. This creates one unassigned job linked to the immutable approved estimate and pricing. Technician selection is not currently inside the conversion dialog; assign the technician later in Jobs or Dispatch.', sources: estimates, tests: [procedure('manager','/estimates',[['approved'],['convert approved estimate'],['property','category'],['quarter-hour','time'],['unassigned'],['jobs','dispatch'],['immutable','pricing']]), denied('technician','/estimates')] }),

  // Jobs, scheduling and dispatch (15)
  entry({ id: 'JSD-01', category: 'Jobs, scheduling and dispatch', question: 'How do I create a one-time job for an existing customer?', supportedRoles: ['owner','admin','manager'], navigation: 'Jobs > New Job > One-time appointment', answer: 'Open Jobs, choose New Job, select an existing customer and service property, keep One-time appointment, enter service, date, quarter-hour time and duration, optionally assign an eligible field worker, then Schedule Job.', sources: jobs, tests: [procedure('manager','/jobs',[['jobs'],['new job'],['existing customer'],['service property'],['one-time'],['quarter-hour'],['schedule job']]), denied('technician','/jobs')] }),
  entry({ id: 'JSD-02', category: 'Jobs, scheduling and dispatch', question: 'How do I create a recurring weekly, monthly, or quarterly appointment?', supportedRoles: ['owner','admin','manager'], navigation: 'Jobs > New Job > Recurring appointment', answer: 'Choose Recurring appointment, select the frequency/pattern and first service date, configure preferred technician and fallback behavior, review availability, then save. The recurring Service Plan creates future jobs.', sources: [...jobs,...recurring], tests: [procedure('manager','/jobs',[['recurring'],['frequency','weekly','monthly','quarterly'],['first','date'],['preferred technician'],['service plan']])] }),
  entry({ id: 'JSD-03', category: 'Jobs, scheduling and dispatch', question: 'Can I assign a technician before saving a new job?', supportedRoles: ['owner','admin','manager'], navigation: 'Jobs > New Job > Assigned technician', answer: 'Yes. Select Assigned technician before saving. Only field-eligible staff appear; review schedule conflicts and alternatives before Schedule Job.', sources: jobs, tests: [procedure('manager','/jobs',[['assigned technician'],['before','saving'],['field','eligible'],['conflict','alternative']])] }),
  entry({ id: 'JSD-04', category: 'Jobs, scheduling and dispatch', question: 'What happens if the selected technician has a schedule conflict?', supportedRoles: ['owner','admin','manager'], navigation: 'Jobs > New/Edit Job > Technician and schedule', answer: 'The availability check shows overlapping work and alternate times/dates. Choose a conflict-free alternative or deliberately leave unassigned/review the warning; travel time is not included in the conflict check.', sources: [...jobs,'routeLogisticsWeb/src/components/TechnicianAvailability.jsx'], tests: [procedure('manager','/jobs',[['conflict'],['alternate','alternative'],['time','date'],['travel','not included']])] }),
  entry({ id: 'JSD-05', category: 'Jobs, scheduling and dispatch', question: 'Why is a manager or owner missing from the assignment list?', supportedRoles: ['owner','admin','manager'], navigation: 'Company > Team > Field work settings', answer: 'Role and field-work eligibility are separate. Open Company and enable field assignment for that staff member. Office-only managers retain management access but do not appear for new field assignments.', sources: ['routeLogisticsWeb/src/pages/CompanySetupPage.jsx','routeLogisticsMobile/components/StaffAvailabilityEditor.js'], tests: [procedure('manager','/company-setup',[['role'],['field work','field assignment'],['office-only'],['management access']])] }),
  entry({ id: 'JSD-06', category: 'Jobs, scheduling and dispatch', question: 'How do I cancel an appointment?', supportedRoles: ['owner','admin','manager'], navigation: 'Jobs > View/Edit job > Cancel appointment', answer: 'Open the job and choose Cancel appointment, then confirm. Scheduled work can be cancelled and retained in history; in-progress or completed work cannot be cancelled through this action.', sources: jobs, tests: [procedure('manager','/jobs',[['cancel'],['confirm'],['retained','history'],['in-progress'],['completed']])] }),
  entry({ id: 'JSD-07', category: 'Jobs, scheduling and dispatch', question: 'How do I permanently delete a test job?', supportedRoles: ['owner','admin','manager'], navigation: 'Jobs > job actions/details > Permanently delete', answer: 'Choose Permanently delete and confirm. It is limited to authorized management, is unavailable for in-progress work and estimate visits, and is intended for records that may safely be removed.', sources: jobs, tests: [procedure('manager','/jobs',[['permanently delete'],['confirm'],['in-progress'],['estimate visit']])] }),
  entry({ id: 'JSD-08', category: 'Jobs, scheduling and dispatch', question: 'How do I skip one recurring visit or pause recurring service for a period?', supportedRoles: ['owner','admin','manager'], navigation: 'Service Plans > plan > Pause', answer: 'Open Service Plans, choose Pause, then select Skip the next occurrence only, Pause through a date, or Pause indefinitely. Already-created Jobs remain individually manageable. Use Resume to reactivate an indefinite pause.', sources: recurring, tests: [procedure('manager','/service-plans',[['service plans'],['pause'],['skip','next occurrence'],['through','date'],['indefinite'],['already','jobs'],['resume']])] }),
  entry({ id: 'JSD-09', category: 'Jobs, scheduling and dispatch', question: 'How do I reassign a job from the web app?', supportedRoles: ['owner','admin','manager'], navigation: 'Dispatch or Jobs > Assigned to', answer: 'Open Dispatch or the job in Jobs, select a different eligible field worker in Assigned to, review conflicts/availability, and save. A technician cannot self-reassign without management.', sources: [...jobs,...dispatch], tests: [procedure('manager','/dispatch',[['dispatch','jobs'],['assigned to','reassign'],['eligible'],['conflict','availability']]), denied('technician','/my-work')] }),
  entry({ id: 'JSD-10', category: 'Jobs, scheduling and dispatch', question: 'How does a manager reassign scheduled work in the mobile app?', supportedRoles: ['owner','admin','manager'], navigation: 'Mobile > Management > Scheduled jobs > job > reassignment controls', answer: 'Switch to Management mode, open Scheduled jobs, select the job and choose an eligible staff member. Review conflicts before confirming. Technicians instead submit a reassignment request.', sources: ['routeLogisticsMobile/screens/ManagementScreen.js','routeLogisticsMobile/services/managementPolicy.js','routeLogisticsMobile/components/JobReassignmentRequest.js'], tests: [procedure('manager','/dispatch',[['management'],['scheduled jobs'],['eligible'],['conflict'],['technician','request']])] }),
  entry({ id: 'JSD-11', category: 'Jobs, scheduling and dispatch', question: 'How do I calculate and save a technician’s daily route?', supportedRoles: ['owner','admin','manager'], navigation: 'Daily Routes > technician/date > Load jobs > Calculate route > Save stop order', answer: 'Open Daily Routes, select the technician and service date, choose Load jobs, set the start/departure options, choose Calculate route, review warnings, and then choose Save stop order. Route optimization requires valid service locations.', sources: dispatch, tests: [procedure('manager','/routes',[['daily routes'],['technician'],['service date'],['calculate route'],['save stop order'],['valid','location']])] }),
  entry({ id: 'JSD-12', category: 'Jobs, scheduling and dispatch', question: 'How do I show jobs and technician locations on the dispatch map?', supportedRoles: ['owner','admin','manager'], navigation: 'Dispatch > Show dispatch map > Locate service addresses', answer: 'Open Dispatch, choose the service date and filters, show the map, and locate unmapped service addresses in controlled batches. Job markers and on-duty team positions are distinct; GPS freshness does not prove availability.', sources: dispatch, tests: [procedure('manager','/dispatch',[['dispatch'],['map'],['service address'],['job','marker'],['on-duty','team'],['gps','availability']])] }),
  entry({ id: 'JSD-13', category: 'Jobs, scheduling and dispatch', question: 'Where do I review potentially late, overdue, or reassignment-requested jobs?', supportedRoles: ['owner','admin','manager'], navigation: 'Dispatch > attention filters', answer: 'Use Dispatch and select Potentially late, Overdue, or Reassignment requested. These indicators do not automatically change assignments or prove technician absence.', sources: dispatch, tests: [procedure('manager','/dispatch',[['dispatch'],['potentially late'],['overdue'],['reassignment requested'],['do not','assignment','absence']])] }),
  entry({ id: 'JSD-14', category: 'Jobs, scheduling and dispatch', question: 'How do job statuses change from scheduled to completed?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: 'Mobile > assigned job > field workflow', answer: 'Assigned field staff progress authorized work through en-route/in-progress and completion using the job workflow. Completion requires work completed text and preserves visit/checklist/photo drafts. Managers can review status but must not bypass assignment controls.', sources: mobileWork, tests: [procedure('technician','/my-work',[['assigned'],['en-route','in-progress'],['complete'],['work completed'],['draft']])] }),
  entry({ id: 'JSD-15', category: 'Jobs, scheduling and dispatch', question: 'Why can’t I see or open a job that should be assigned to me?', supportedRoles: ['owner','admin','manager','technician'], navigation: 'Mobile > Field/Schedule or Web > Jobs/Dispatch', answer: 'Confirm the signed-in workspace, active membership, current assignment and non-cancelled status. Refresh assigned work after reconnecting. Technicians see only authorized assigned jobs; ask management to correct assignment rather than weakening access.', sources: [...mobileWork,'routeLogisticsMobile/services/useJobResources.js','functions/security.js'], tests: [procedure('technician','/my-work',[['workspace','membership'],['assignment'],['refresh','reconnect'],['assigned jobs'],['management']])] }),

  // Technician mobile workflows (15)
  entry({ id: 'MOB-01', category: 'Technician mobile workflows', question: 'How does a technician sign in on mobile with a password or email code?', supportedRoles: ['owner','admin','manager','technician'], navigation: 'Mobile Login > Password or Email code', answer: 'Choose Password or Email code. For Email code request the newest six-digit code and enter it within ten minutes. An invitation must still be accepted separately before company access exists.', sources: auth, tests: [procedure('technician','/my-work',[['password'],['email code'],['six-digit'],['ten minutes','expires'],['invitation','separate']])] }),
  entry({ id: 'MOB-02', category: 'Technician mobile workflows', question: 'What is the difference between Field and Management mode?', supportedRoles: ['owner','admin','manager'], navigation: 'Mobile mode toggle', answer: 'Field mode shows the signed-in person’s assigned work. Management mode exposes authorized operational summaries and management actions. A technician has Field access only; switching mode does not change role or permissions.', sources: [...mobileShell,'routeLogisticsMobile/services/mobileMode.js'], tests: [procedure('manager','/',[['field'],['management'],['assigned work'],['does not','role','permission']]), procedure('technician','/my-work',[['field'],['technician'],['permission']])] }),
  entry({ id: 'MOB-03', category: 'Technician mobile workflows', question: 'How do I go On Duty or Off Duty?', supportedRoles: ['owner','admin','manager','technician'], navigation: 'Mobile Home header > On Duty/Off Duty > Work shift', answer: 'Tap the status button in the Home header, then Start shift or End shift. On Duty is a server shift state; Off Duty stops work-location sharing on the device after the end is confirmed.', sources: ['routeLogisticsMobile/components/WorkLocation.js','functions/locations.js'], tests: [procedure('technician','/my-work',[['on duty','off duty'],['home','header'],['start shift','end shift'],['location','sharing']])] }),
  entry({ id: 'MOB-04', category: 'Technician mobile workflows', question: 'When is my location shared with the manager or owner?', supportedRoles: ['owner','admin','manager','technician'], navigation: 'Mobile Home > On Duty > Work shift', answer: 'Location is shared only during an active On Duty shift after device permission/consent. Background sharing depends on the selected option and OS permission. End shift to stop; recording a visit does not start continuous sharing.', sources: ['routeLogisticsMobile/components/WorkLocation.js','routeLogisticsMobile/services/workTracking.js'], tests: [procedure('technician','/my-work',[['on duty','shift'],['permission','consent'],['background'],['end shift'],['visit','does not']])] }),
  entry({ id: 'MOB-05', category: 'Technician mobile workflows', question: 'Can I open and work on a job while offline?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: 'Mobile > previously loaded assigned job', answer: 'Yes, only if the authorized job was opened/cached online first. Offline work is saved in the company/user/role/membership scope and must synchronize after reconnection; access is revalidated before server changes.', sources: mobileWork, tests: [procedure('technician','/my-work',[['opened','online','cached'],['offline'],['company','user','scope'],['reconnect','sync'],['access','revalidated']])] }),
  entry({ id: 'MOB-06', category: 'Technician mobile workflows', question: 'Will work-note drafts survive closing or restarting the mobile app?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: 'Job Details > Work notes > Save work notes', answer: 'Typed work notes are persisted per company/user/job and restored after restart. Use Save work notes to queue synchronization. Do not discard the draft until Saved to server is shown.', sources: mobileWork, tests: [procedure('technician','/my-work',[['work notes'],['company','user','job'],['restart','restore'],['save work notes'],['saved to server'],['do not','discard']])] }),
  entry({ id: 'MOB-07', category: 'Technician mobile workflows', question: 'How do I take or choose a job photo and what happens offline?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: 'Job Details > Photos > Camera or Gallery', answer: 'Open Photos and choose Camera or Gallery, grant permission when requested, select/capture the image and save/queue it. The retained file and operation survive offline restart and show waiting/sync/error state with retry.', sources: ['routeLogisticsMobile/components/JobPhotos.js','routeLogisticsMobile/services/offline.js'], tests: [procedure('technician','/my-work',[['photo'],['camera','gallery'],['permission'],['offline','restart'],['waiting','sync','retry']])] }),
  entry({ id: 'MOB-08', category: 'Technician mobile workflows', question: 'How do I record arrival at a job?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: 'Job Details > Visit record > Record arrival', answer: 'Choose Record arrival, optionally attach a current GPS sample, then save the visit event. The original event time and operation ID are retained offline. Arrival evidence does not independently prove access.', sources: mobileWork, tests: [procedure('technician','/my-work',[['record arrival'],['gps','optional'],['visit event'],['offline'],['does not','prove','access']])] }),
  entry({ id: 'MOB-09', category: 'Technician mobile workflows', question: 'How do I record departure from a job?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: 'Job Details > Visit record > Record departure', answer: 'Choose Record departure, optionally include a current GPS sample, then save. Confirm the green/completed state or synchronization label before leaving the workflow.', sources: mobileWork, tests: [procedure('technician','/my-work',[['record departure'],['gps','optional'],['save'],['sync','saved']])] }),
  entry({ id: 'MOB-10', category: 'Technician mobile workflows', question: 'What should I record if I cannot access the property?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: "Job Details > Visit record > Couldn't access property", answer: 'Choose Couldn’t access property, enter the required explanation, optionally include GPS evidence, and save the access-blocked visit event. This records evidence; it does not automatically complete or cancel the job.', sources: mobileWork, tests: [procedure('technician','/my-work',[['access','property'],['explanation','note'],['gps','optional'],['does not','complete','cancel']])] }),
  entry({ id: 'MOB-11', category: 'Technician mobile workflows', question: 'Why do I see a service checklist and which template should I use?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: 'Job Details > Service checklist', answer: 'A manager attaches the company/service-appropriate template. Technicians complete the pinned template but cannot choose or replace it. The management catalog is filtered for the company/job and the server rejects an unrelated built-in template. Saved report versions remain tied to the job assignment.', sources: ['routeLogisticsMobile/components/ServiceChecklist.js','routeLogisticsWeb/src/components/ServiceChecklist.jsx','functions/serviceForms.js'], tests: [procedure('technician','/my-work',[['manager'],['template'],['technician','cannot','pinned'],['company','job','service'],['reject','unrelated'],['version','assignment']])] }),
  entry({ id: 'MOB-12', category: 'Technician mobile workflows', question: 'What must I do before completing a job?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: 'Job Details > Complete > Review completion', answer: 'Save or explicitly discard open notes/photo/checklist/visit drafts, enter Work completed, optional hours/notes and estimate-visit outcome when applicable, review the confirmation, then submit. Product application is optional unless company policy says otherwise.', sources: mobileWork, tests: [procedure('technician','/my-work',[['save','discard'],['draft'],['work completed'],['review completion'],['product application','optional']])] }),
  entry({ id: 'MOB-13', category: 'Technician mobile workflows', question: 'What do I do when mobile synchronization fails?', supportedRoles: ['owner','admin','manager','technician-assigned'], navigation: 'Job Details > synchronization state > Retry', answer: 'Keep the local draft, reconnect, use the specific retry control and wait for Saved to server. Do not recreate the work or discard the stable operation; conflicts require management review.', sources: mobileWork, tests: [procedure('technician','/my-work',[['keep','draft'],['reconnect'],['retry'],['saved to server'],['do not','discard'],['conflict','management']])] }),
  entry({ id: 'MOB-14', category: 'Technician mobile workflows', question: 'How does a technician request that a job be reassigned?', supportedRoles: ['technician-assigned'], navigation: 'Job Details > Request reassignment', answer: 'Open the assigned nonterminal job, choose Request reassignment, select a supported reason and add appropriate notes. Management receives the request and must resolve it; the technician does not change the assignment directly.', sources: ['routeLogisticsMobile/components/JobReassignmentRequest.js','functions/jobExceptions.js'], tests: [procedure('technician','/my-work',[['request reassignment'],['reason'],['management'],['does not','assignment','directly']])] }),
  entry({ id: 'MOB-15', category: 'Technician mobile workflows', question: 'Where can I change mobile appearance and find the app version?', supportedRoles: ['owner','admin','manager','technician'], navigation: 'Mobile > Settings > Appearance / About', answer: 'Open Settings. Appearance offers System, Light and Dark and stores the choice on the device. Open About for the app version/build used by support.', sources: mobileShell, tests: [procedure('technician','/my-work',[['settings'],['appearance'],['system'],['light'],['dark'],['device'],['about'],['version']])] }),

  // Billing, payments and approvals (10)
  entry({ id: 'BIL-01', category: 'Billing, payments and approvals', question: 'How do I create an invoice from a completed job?', supportedRoles: ['owner','admin'], navigation: 'Jobs > View completed billable job > Create Invoice', answer: 'Open the completed billable job in Jobs, choose Create Invoice, review the preview/source details and explicitly generate the draft. Estimate visits are nonbillable and cannot use this path.', sources: invoices, tests: [procedure('owner','/invoices',[['jobs'],['completed','billable'],['create invoice'],['preview'],['estimate visit','nonbillable']]), denied('manager','/jobs'), denied('technician','/my-work')] }),
  entry({ id: 'BIL-02', category: 'Billing, payments and approvals', question: 'Can a manager or technician create or view invoices?', supportedRoles: ['owner','admin'], navigation: 'Invoices (owner/admin only)', answer: 'No. The current capability policy gives invoice read/manage access to owners and administrators only. Managers and technicians must ask an authorized owner or administrator.', sources: [...invoices,...accounts], tests: [denied('manager','/invoices'), denied('technician','/my-work')] }),
  entry({ id: 'BIL-03', category: 'Billing, payments and approvals', question: 'How do I review an invoice before generating it?', supportedRoles: ['owner','admin'], navigation: 'Jobs > completed job > Create Invoice > preview dialog', answer: 'Open Create Invoice from eligible completed work, review customer/source, immutable completed work, line items, totals and warnings, then explicitly create. Do not rely on the assistant to perform the financial action.', sources: invoices, tests: [procedure('owner','/invoices',[['preview'],['customer','source'],['line item','total'],['explicit'],['assistant','does not']])] }),
  entry({ id: 'BIL-04', category: 'Billing, payments and approvals', question: 'How do I correct an invoice after it has been issued?', supportedRoles: ['owner','admin'], navigation: 'Invoices > invoice actions > Void / Review replacement', answer: 'Do not silently rewrite issued history. Void the eligible invoice with confirmation, then use Review replacement for its job. Payment locks must be resolved first and audit history is retained.', sources: invoices, tests: [procedure('owner','/invoices',[['void'],['review replacement'],['payment lock'],['audit','history'],['do not','rewrite']])] }),
  entry({ id: 'BIL-05', category: 'Billing, payments and approvals', question: 'What does a Stripe test payment change on an invoice?', supportedRoles: ['owner','admin','authorized customer'], navigation: 'Invoices > sent invoice > Test card payment', answer: 'In test mode the Payment Element creates a test PaymentIntent. Signed webhook reconciliation updates testPaymentStatus and payment audit state, but does not mark the real invoice paid.', sources: payments, tests: [procedure('owner','/invoices',[['test'],['payment'],['webhook'],['testpaymentstatus','test payment status'],['does not','invoice','paid']])] }),
  entry({ id: 'BIL-06', category: 'Billing, payments and approvals', question: 'Can Route Logistics collect live card payments now?', supportedRoles: [], navigation: 'No enabled production workflow', answer: 'No. Live payments remain disabled unless live mode is configured and explicitly approved. Use only the controlled test flow; the assistant cannot enable payments.', status: 'disabled', sources: payments, tests: [unavailable('owner','/invoices',[['live'],['disabled'],['test'],['cannot','enable']])] }),
  entry({ id: 'BIL-07', category: 'Billing, payments and approvals', question: 'What invoices and payments can a customer see in the portal?', supportedRoles: ['authorized customer'], navigation: 'Customer Portal > provider > invoices/payment history', answer: 'After email-code verification, the customer sees only invoices and payment history linked to their authorized provider association and matching portal identity. Provider switching remains tenant-scoped.', sources: ['routeLogisticsWeb/src/pages/CustomerPortalPage.jsx','functions/portal.js','functions/payments.js'], tests: [procedure('owner','/invoices',[['customer portal'],['email','code'],['authorized','provider'],['tenant','scoped'],['invoice','payment history']])] }),
  entry({ id: 'BIL-08', category: 'Billing, payments and approvals', question: 'How do I email an invoice and verify delivery?', supportedRoles: ['owner','admin'], navigation: 'Invoices > Email invoice', answer: 'For a draft/sent eligible invoice choose Email invoice. The app queues delivery and records status; sent status is not the same as inbox delivery, so review delivery/audit status when needed.', sources: ['routeLogisticsWeb/src/pages/InvoicesPage.jsx','functions/invoiceEmail.js','functions/mail.js'], tests: [procedure('owner','/invoices',[['email invoice'],['queue'],['delivery','status'],['not','inbox']])] }),
  entry({ id: 'BIL-09', category: 'Billing, payments and approvals', question: 'Is QuickBooks synchronization available and can it export accounting data?', supportedRoles: ['owner','admin-read'], navigation: 'Integrations > QuickBooks Online', answer: 'The owner can connect the company sandbox and review status/options/mappings. Accounting exports are currently disabled; production synchronization is not approved. Do not use Export reviewed record until writes are deliberately enabled for a controlled environment.', status: 'limited', sources: ['routeLogisticsWeb/src/pages/IntegrationsPage.jsx','functions/quickBooks.js'], tests: [procedure('owner','/integrations',[['quickbooks'],['owner'],['sandbox'],['exports','disabled'],['production','not','approved']])] }),
  entry({ id: 'BIL-10', category: 'Billing, payments and approvals', question: 'How do I choose the default QuickBooks income account and service item?', supportedRoles: ['owner'], navigation: 'Integrations > Accounting defaults', answer: 'Connect QuickBooks, refresh available options, search the active income accounts and service items, choose both defaults and Save defaults. Empty lists must be populated in QuickBooks first. Saving preferences does not create or modify QuickBooks records.', sources: ['routeLogisticsWeb/src/pages/IntegrationsPage.jsx','functions/quickBooks.js'], tests: [procedure('owner','/integrations',[['accounting defaults'],['refresh'],['income account'],['service item'],['save defaults'],['does not','create','modify']]), denied('manager','/integrations')] }),

  // Accounts, permissions and troubleshooting (15)
  entry({ id: 'APT-01', category: 'Accounts, permissions and troubleshooting', question: 'What can a company owner do that other roles cannot?', supportedRoles: ['owner'], navigation: 'Company and all authorized operational pages', answer: 'The owner has company edit, team management, ownership transfer, finance and integration management in addition to operations. Owner-reserved actions include invitations/role changes, ownership transfer and QuickBooks connection/defaults.', sources: accounts, tests: [procedure('owner','/company-setup',[['owner'],['team'],['ownership'],['invoice','finance'],['integration','quickbooks']])] }),
  entry({ id: 'APT-02', category: 'Accounts, permissions and troubleshooting', question: 'What can a manager do and what is restricted?', supportedRoles: ['manager'], navigation: 'Operational pages allowed by capability policy', answer: 'Managers can manage customers, jobs, assignments, estimates, plans, routes, dispatch, locations, operational reports and reviews. They cannot manage invoices/financial reports, company ownership, team invitations/roles or owner-only integrations.', sources: accounts, tests: [procedure('manager','/',[['customers'],['jobs','dispatch'],['estimate'],['cannot','invoice','financial'],['cannot','owner','team','integration']])] }),
  entry({ id: 'APT-03', category: 'Accounts, permissions and troubleshooting', question: 'What can a technician access?', supportedRoles: ['technician'], navigation: 'Dashboard/My Work, assigned Estimates, Routes, read-only customer/company context', answer: 'Technicians can read authorized company/customer/job context, work assigned jobs, prepare assigned estimates, read routes and share their own location. They cannot schedule/assign company work, manage customers, invoices, team or integrations.', sources: accounts, tests: [procedure('technician','/my-work',[['assigned','jobs'],['assigned','estimate'],['route'],['own','location'],['cannot','schedule','invoice','team']])] }),
  entry({ id: 'APT-04', category: 'Accounts, permissions and troubleshooting', question: 'How does the owner invite a technician or manager?', supportedRoles: ['owner'], navigation: 'Company > Team > invitation email/role > Send invite', answer: 'Open Company, enter the email, select Technician or Manager and send the invitation. The role is owner-selected. If email is disabled or delayed, copy the generated invitation link securely.', sources: ['routeLogisticsWeb/src/pages/CompanySetupPage.jsx','functions/invitations.js','functions/mail.js'], tests: [procedure('owner','/company-setup',[['company'],['email'],['technician','manager'],['invitation'],['role'],['link']]), denied('manager','/company-setup')] }),
  entry({ id: 'APT-05', category: 'Accounts, permissions and troubleshooting', question: 'Where does an invited new user set a password?', supportedRoles: ['invited user'], navigation: 'Invitation link > Create account > verify email > return to invitation > Accept invitation', answer: 'A new user creates a personal Route Logistics login from the invitation flow, sets the password during account creation, verifies email, then returns to Accept invitation. Acceptance joins the existing company and does not create a team.', sources: ['routeLogisticsWeb/src/pages/AcceptInvitePage.jsx','routeLogisticsWeb/src/pages/SignUpPage.jsx'], tests: [procedure('technician','/',[['invitation'],['create','login','account'],['password'],['verify','email'],['accept invitation'],['does not','create','team']])] }),
  entry({ id: 'APT-06', category: 'Accounts, permissions and troubleshooting', question: 'What should an invited user do if they already have a Route Logistics account?', supportedRoles: ['invited user'], navigation: 'Invitation link > Sign in > return > Accept invitation', answer: 'Sign in with the existing password or use Forgot password, then reopen the same invitation and choose Accept invitation while signed in with the invited email.', sources: ['routeLogisticsWeb/src/pages/AcceptInvitePage.jsx'], tests: [procedure('technician','/',[['existing','account'],['sign in'],['forgot password'],['invitation'],['accept invitation'],['invited email']])] }),
  entry({ id: 'APT-07', category: 'Accounts, permissions and troubleshooting', question: 'How do I reset a forgotten password?', supportedRoles: ['owner','admin','manager','technician'], navigation: 'Login > Forgot password? > Send password reset link', answer: 'On Login choose Forgot password?, enter the email and send the reset link. After changing the password, sign in again; reopen a pending invitation if one still needs acceptance.', sources: auth, tests: [procedure('manager','/',[['forgot password'],['reset','link'],['sign in'],['invitation']])] }),
  entry({ id: 'APT-08', category: 'Accounts, permissions and troubleshooting', question: 'How does email-code login work for staff?', supportedRoles: ['verified owner','verified admin','verified manager','verified technician'], navigation: 'Login > Email code > Email a sign-in code', answer: 'Choose Email code, request a code for a verified staff account, enter the newest six-digit code within ten minutes and sign in. Codes are single-use/rate-limited; customer portal codes belong on the portal.', sources: auth, tests: [procedure('manager','/',[['email code'],['verified'],['six-digit'],['ten minutes','expires'],['single-use','rate'],['customer portal']])] }),
  entry({ id: 'APT-09', category: 'Accounts, permissions and troubleshooting', question: 'What does Remember me store?', supportedRoles: ['owner','admin','manager','technician'], navigation: 'Login > Remember me', answer: 'It stores only the email address on that device for convenience. It does not store the password or bypass authentication.', sources: auth, tests: [procedure('technician','/',[['remember'],['email'],['device'],['does not','password','bypass']])] }),
  entry({ id: 'APT-10', category: 'Accounts, permissions and troubleshooting', question: 'How do I permanently delete my mobile account?', supportedRoles: ['owner','admin','manager','technician'], navigation: 'Mobile > Settings > Account and legal > Delete account', answer: 'Open Settings and Delete account, review pending offline work, sign in recently if required, type the full current email exactly and complete the destructive confirmation. Personal sign-in is deleted while required business/audit records are retained.', sources: ['routeLogisticsMobile/components/DeleteAccountSettings.js','functions/accountDeletion.js'], tests: [procedure('technician','/my-work',[['settings'],['delete account'],['offline','pending'],['sign in'],['email'],['confirmation'],['business','audit','retained']])] }),
  entry({ id: 'APT-11', category: 'Accounts, permissions and troubleshooting', question: 'Why do I get a missing or insufficient permissions error after my role changes?', supportedRoles: ['owner','admin','manager','technician'], navigation: 'Refresh access / sign out and sign in', answer: 'The active membership, token role and membership ID must match. Use Refresh access or sign out/in to obtain current claims. If the membership is inactive or wrong, the owner must correct it; retrying must not bypass tenant checks.', sources: ['functions/security.js','functions/claims.js','routeLogisticsWeb/src/contexts/AuthContext.jsx'], tests: [procedure('manager','/',[['membership'],['role'],['refresh access','sign out'],['claims'],['owner'],['tenant']])] }),
  entry({ id: 'APT-12', category: 'Accounts, permissions and troubleshooting', question: 'Can I switch to another company workspace with the same account?', supportedRoles: ['owner','admin','manager','technician'], navigation: 'Workspace access selection when multiple memberships are available', answer: 'Only active authorized memberships can be selected. Switching refreshes claims and data scope; unsaved/offline work remains scoped to the original company and must not be mixed across workspaces.', status: 'limited', sources: ['routeLogisticsMobile/screens/WorkspaceScreen.js','routeLogisticsMobile/screens/WorkspaceAccessScreen.js','functions/workspace.js'], tests: [procedure('manager','/',[['active','membership'],['switch','workspace'],['claims','scope'],['offline','original company'],['not','mixed']])] }),
  entry({ id: 'APT-13', category: 'Accounts, permissions and troubleshooting', question: 'Can the AI Assistant change jobs, customers, invoices, or permissions for me?', supportedRoles: ['owner','admin','manager','technician'], navigation: 'Assistant chat', answer: 'No. The assistant is guidance-only and offers authorized navigation. It does not execute customer, job, financial, credential or permission changes.', sources: assistant, tests: [procedure('owner','/',[['guidance'],['does not','cannot'],['job','customer'],['invoice','financial'],['permission']])] }),
  entry({ id: 'APT-14', category: 'Accounts, permissions and troubleshooting', question: 'How do I contact a human or report a problem from the assistant?', supportedRoles: ['owner','admin','manager','technician'], navigation: 'Assistant > Support or Report a Problem', answer: 'Use the existing support workflow: open Support or Report a Problem, review the disclosure, enter only necessary non-customer/non-financial details and submit to Workside Support. A handoff is not automatic from an ordinary question.', sources: assistant, tests: [procedure('manager','/',[['support','report a problem'],['disclosure'],['without','customer','financial'],['workside'],['not','automatic']])] }),
  entry({ id: 'APT-15', category: 'Accounts, permissions and troubleshooting', question: 'How do I close or reset an assistant conversation, and what should I do if it is unavailable?', supportedRoles: ['owner','admin','manager','technician'], navigation: 'Assistant > New conversation / minimize; retry on provider error', answer: 'Use the assistant’s new/reset conversation control to close the existing session and start clean; minimizing preserves it in session storage. If the provider is unavailable, retry later and use verified help topics. Closing a conversation does not change application data.', sources: assistant, tests: [procedure('manager','/',[['conversation','session'],['close','new','reset'],['minimize','preserve'],['unavailable','retry'],['does not','data']])] }),
];

const expectedCounts = new Map([
  ['Customers, prospects and estimates', 20],
  ['Jobs, scheduling and dispatch', 15],
  ['Technician mobile workflows', 15],
  ['Billing, payments and approvals', 10],
  ['Accounts, permissions and troubleshooting', 15],
]);

export function validateCatalog() {
  const issues = [];
  const ids = new Set();
  for (const row of catalog) {
    if (ids.has(row.id)) issues.push(`Duplicate id ${row.id}`);
    ids.add(row.id);
    for (const field of ['question','navigation','verifiedAnswer']) if (!row[field]) issues.push(`${row.id} missing ${field}`);
    if (!row.sourceReferences?.length) issues.push(`${row.id} has no source references`);
    if (!row.assistantTests?.length) issues.push(`${row.id} has no assistant tests`);
  }
  for (const [category, count] of expectedCounts) {
    const actual = catalog.filter(row => row.category === category).length;
    if (actual !== count) issues.push(`${category}: expected ${count}, found ${actual}`);
  }
  if (catalog.length !== 75) issues.push(`Expected 75 questions, found ${catalog.length}`);
  return issues;
}

